+        }
+
+        @Override
+        public float score() throws IOException {
+            return simScorer.score(iterator.docID(), freq());
+        }
+
+        @Override
+        public DocIdSetIterator iterator() {
+            return iterator;
+        }
+
+        @Override
+        public float getMaxScore(int upTo) throws IOException {
+            return Float.POSITIVE_INFINITY;
+        }
+    }
+}

